(function(){
'use strict';
const KEY='panludiq.guest.v1';let profile=null,onReady=null;
function valid(p){return p&&p.version===1&&typeof p.id==='string'&&/^guest_[a-zA-Z0-9-]+$/.test(p.id)&&typeof p.nickname==='string'&&p.nickname.trim().length>0&&Array.from(p.nickname).length<=12}
try{let p=JSON.parse(localStorage.getItem(KEY));if(valid(p))profile=p}catch{}
function generate(){let id=typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);return 'guest_'+id}
function refresh(){document.querySelectorAll('[data-guest]').forEach(b=>{b.textContent=profile?profile.nickname+' · 게스트':'게스트 입장';b.setAttribute('aria-label',profile?'게스트 닉네임 변경':'게스트로 입장')})}
function open(callback){onReady=callback||null;const form=document.querySelector('#guest-form');form.reset();document.querySelector('#guest-name').value=profile?.nickname||'';document.querySelector('#guest-error').textContent='';document.querySelector('#guest-dialog').showModal()}
function ensure(callback){if(profile){if(callback)callback(profile)}else open(callback)}
const dialog=document.createElement('dialog');dialog.id='guest-dialog';dialog.setAttribute('aria-labelledby','guest-heading');dialog.innerHTML='<form id="guest-form"><p class="eyebrow">WELCOME TO PANLUDIQ</p><h2 id="guest-heading">게스트로 가볍게 시작해요.</h2><p>가입 없이 닉네임만 정하면 게임을 즐길 수 있어요.</p><label for="guest-name">닉네임 <small>선택 · 최대 12글자</small></label><input id="guest-name" name="nickname" autocomplete="off" placeholder="비워두면 자동으로 정해드려요" aria-describedby="guest-error"><p id="guest-error" class="message" role="status" aria-live="polite"></p><button class="primary" type="submit">게스트로 시작하기 →</button><p class="note">계정 로그인 없이 이 브라우저에 게스트 정보를 저장합니다. 기기 간 동기화는 지원하지 않아요. 미니 체스는 온라인 친구 초대 대전과 로컬 2인 모드를 지원합니다.</p></form>';
document.body.appendChild(dialog);dialog.addEventListener('cancel',e=>{if(!profile)e.preventDefault()});document.querySelector('#guest-form').addEventListener('submit',e=>{e.preventDefault();let name=document.querySelector('#guest-name').value.trim();if(Array.from(name).length>12||/[\u0000-\u001f\u007f]/.test(name)){document.querySelector('#guest-error').textContent='닉네임은 제어문자 없이 12글자 이하로 입력해주세요.';return}if(!name)name='게스트'+String(Math.floor(Math.random()*9000)+1000);profile={version:1,id:profile?.id||generate(),nickname:name};let saved=true;try{localStorage.setItem(KEY,JSON.stringify(profile))}catch{saved=false}refresh();dialog.close();if(!saved){let n=document.createElement('p');n.className='guest-storage-note';n.setAttribute('role','status');n.textContent='브라우저 저장이 제한되어 이번 페이지에서만 게스트로 이용합니다.';document.querySelector('header').after(n)}let callback=onReady;onReady=null;if(callback)callback(profile)});
document.querySelectorAll('[data-guest]').forEach(b=>b.addEventListener('click',()=>open()));window.Guest={ensure,getProfile:()=>profile};refresh();ensure();
})();
